<section class="section-block"><div class="section-heading"><h2>Agenda semanal</h2><p>Cada alteração cria uma nova versão e preserva aulas com histórico.</p></div><div class="card list-card">@foreach($classGroup->schedules->sortByDesc('valid_from') as $schedule)<div class="list-row"><span><strong>{{ $weekdays[$schedule->weekday] }} · {{ substr($schedule->start_time,0,5) }} às {{ substr($schedule->end_time,0,5) }}</strong><small>{{ $schedule->valid_from->format('d/m/Y') }} até {{ $schedule->valid_until?->format('d/m/Y') ?: 'atual' }}{{ $schedule->location_name ? ' · '.$schedule->location_name : '' }}{{ $schedule->teacher?->person ? ' · '.$schedule->teacher->person->full_name : '' }}</small></span><span class="status-pill">{{ $schedule->status === 'active' ? 'Atual' : 'Histórico' }}</span></div>@endforeach</div>
