@if($nextSessions->isNotEmpty())<div class="alert alert-info"><strong>Próximas aulas que podem ser afetadas:</strong> {{ $nextSessions->map(fn($item) => $item->session_date->format('d/m').' às '.substr($item->start_time,0,5))->join(', ') }}.</div>@endif
<form class="form-stack" method="post" action="{{ $replaceUrl }}">@csrf<div class="field"><label for="valid_from">Nova agenda a partir de</label><input type="date" id="valid_from" name="valid_from" min="{{ today()->addDay()->format('Y-m-d') }}" required></div><div class="form-stack">@foreach($weekdays as $number=>$label)@php($current=$activeSchedules->get($number))<div class="card form-grid"><label class="check-row"><input type="checkbox" name="schedules[{{ $number }}][enabled]" value="1" @checked($current)>{{ $label }}</label><input type="hidden" name="schedules[{{ $number }}][weekday]" value="{{ $number }}"><div class="field"><label>Início</label><input type="time" name="schedules[{{ $number }}][start_time]" value="{{ $current ? substr($current->start_time,0,5) : '' }}"></div><div class="field"><label>Fim</label><input type="time" name="schedules[{{ $number }}][end_time]" value="{{ $current ? substr($current->end_time,0,5) : '' }}"></div><div class="field"><label>Professor</label><select name="schedules[{{ $number }}][teacher_id]"><option value="">Professor principal</option>@foreach($teachers as $teacher)<option value="{{ $teacher->id }}" @selected($current?->teacher_id===$teacher->id)>{{ $teacher->person->full_name }}</option>@endforeach</select></div><div class="field"><label>Sala/tatame</label><input name="schedules[{{ $number }}][location_name]" value="{{ $current?->location_name }}"></div></div>@endforeach</div><div class="form-actions"><button class="button button-primary">Salvar nova agenda</button></div></form></details>@endif</section>
